SELECT series_group_id, name
FROM series_group
WHERE user_id = #{userId} AND series_group_id = #{seriesGroupId}

SELECT series_group_id, name
FROM series_group
WHERE user_id = #{userId} AND name = #{name}

mapper.insert:
INSERT INTO figure_series_map (user_id, figure_id, series_id)
SELECT DISTINCT l.user_id, l.figure_id, #{fallbackId}
FROM figure_series_map l
WHERE l.user_id = #{userId}
  AND l.series_id IN (SELECT series_id FROM series WHERE user_id = #{userId} AND series_group_id = #{seriesGroupId})
  AND NOT EXISTS (
      SELECT 1 FROM figure_series_map o
      WHERE o.user_id = l.user_id AND o.figure_id = l.figure_id
        AND o.series_id NOT IN (SELECT series_id FROM series WHERE user_id = #{userId} AND series_group_id = #{seriesGroupId})
  )

mapper.delete:
DELETE FROM figure_series_map
WHERE user_id = #{userId}
  AND series_id IN (SELECT series_id FROM series WHERE user_id = #{userId} AND series_group_id = #{seriesGroupId})
